-- blackwall - a colourscheme that follows the wallpaper.
--
-- The palette is generated by theme/blackwall-theme into
-- lua/custom/blackwall_palette.lua, so this scheme re-themes with the rest of
-- the rice whenever setwall runs. This file decides which colour goes where;
-- it never spells a hex value.
--
-- Nothing needs registering: lua/custom/utils/themes.lua builds its list from
-- `vim.fn.getcompletion('', 'color')`, which finds any file in colors/. So
-- this appears in the theme switcher next to the other ten on its own.

local ok, p = pcall(require, 'custom.blackwall_palette')
if not ok then
  vim.notify(
    'blackwall: palette missing - run theme/blackwall-theme',
    vim.log.levels.WARN
  )
  return
end

vim.cmd.highlight 'clear'
if vim.fn.exists 'syntax_on' == 1 then
  vim.cmd.syntax 'reset'
end
vim.o.termguicolors = true
vim.g.colors_name = 'blackwall'

local a = p.ansi

--- Only three roles carry accent: what you are on, what you can follow, and
--- what needs a decision. Everything else is a tier of foreground.
local groups = {
  -- ---- base ------------------------------------------------------------
  Normal = { fg = p.fg, bg = p.bg },
  NormalNC = { fg = p.muted, bg = p.bg },
  NormalFloat = { fg = p.fg, bg = p.raised },
  FloatBorder = { fg = p.edge, bg = p.raised },
  FloatTitle = { fg = p.accent, bg = p.raised, bold = true },
  Cursor = { fg = p.bg, bg = p.cursor },
  lCursor = { fg = p.bg, bg = p.cursor },
  CursorLine = { bg = p.raised },
  CursorColumn = { bg = p.raised },
  ColorColumn = { bg = p.raised },
  -- The line number you are on is the only bright one; the rest recede.
  LineNr = { fg = p.faint },
  CursorLineNr = { fg = p.accent, bold = true },
  SignColumn = { bg = p.bg },
  FoldColumn = { fg = p.faint, bg = p.bg },
  Folded = { fg = p.muted, bg = p.raised },
  VertSplit = { fg = p.edge },
  WinSeparator = { fg = p.edge },
  EndOfBuffer = { fg = p.bg },
  Conceal = { fg = p.faint },
  Directory = { fg = p.accent },
  Title = { fg = p.accent, bold = true },
  MatchParen = { fg = p.warn, bold = true },
  NonText = { fg = p.faint },
  SpecialKey = { fg = p.faint },
  Whitespace = { fg = p.sunken },
  Visual = { bg = p.selection },
  VisualNOS = { bg = p.selection },
  Search = { fg = p.bg, bg = p.warn },
  IncSearch = { fg = p.bg, bg = p.accent },
  CurSearch = { fg = p.bg, bg = p.accent },
  Substitute = { fg = p.bg, bg = p.bad },
  QuickFixLine = { bg = p.selection },
  WinBar = { fg = p.muted, bg = p.bg },
  WinBarNC = { fg = p.faint, bg = p.bg },

  -- ---- messages and prompts --------------------------------------------
  ErrorMsg = { fg = p.bad, bold = true },
  WarningMsg = { fg = p.warn },
  MoreMsg = { fg = p.accent },
  ModeMsg = { fg = p.muted, bold = true },
  Question = { fg = p.accent },
  MsgArea = { fg = p.muted },

  -- ---- statusline and tabs ---------------------------------------------
  StatusLine = { fg = p.muted, bg = p.raised },
  StatusLineNC = { fg = p.faint, bg = p.raised },
  TabLine = { fg = p.faint, bg = p.raised },
  TabLineFill = { bg = p.bg },
  TabLineSel = { fg = p.on_accent or p.bg, bg = p.accent, bold = true },

  -- ---- popup menu -------------------------------------------------------
  Pmenu = { fg = p.muted, bg = p.raised },
  PmenuSel = { fg = p.fg, bg = p.selection, bold = true },
  PmenuSbar = { bg = p.raised_hi },
  PmenuThumb = { bg = p.faint },
  PmenuKind = { fg = p.link, bg = p.raised },
  PmenuExtra = { fg = p.faint, bg = p.raised },
  WildMenu = { fg = p.bg, bg = p.accent },

  -- ---- diff and git ------------------------------------------------------
  DiffAdd = { fg = p.good, bg = p.raised },
  DiffChange = { fg = p.warn, bg = p.raised },
  DiffDelete = { fg = p.bad, bg = p.raised },
  DiffText = { fg = p.fg, bg = p.selection, bold = true },
  Added = { fg = p.good },
  Changed = { fg = p.warn },
  Removed = { fg = p.bad },
  GitSignsAdd = { fg = p.good },
  GitSignsChange = { fg = p.warn },
  GitSignsDelete = { fg = p.bad },

  -- ---- syntax -------------------------------------------------------------
