  Comment = { fg = p.faint, italic = true },
  Constant = { fg = a[3] },
  String = { fg = a[2] },
  Character = { fg = a[2] },
  Number = { fg = a[3] },
  Boolean = { fg = a[3] },
  Float = { fg = a[3] },
  Identifier = { fg = p.fg },
  Function = { fg = p.accent },
  Statement = { fg = a[5] },
  Conditional = { fg = a[5] },
  Repeat = { fg = a[5] },
  Label = { fg = a[5] },
  Operator = { fg = p.muted },
  Keyword = { fg = a[5] },
  Exception = { fg = p.bad },
  PreProc = { fg = a[4] },
  Include = { fg = a[5] },
  Define = { fg = a[5] },
  Macro = { fg = a[4] },
