  DiagnosticInfo = { fg = p.link },
  DiagnosticHint = { fg = p.accent },
  DiagnosticOk = { fg = p.good },
  DiagnosticUnderlineError = { sp = p.bad, undercurl = true },
  DiagnosticUnderlineWarn = { sp = p.warn, undercurl = true },
  DiagnosticUnderlineInfo = { sp = p.link, undercurl = true },
  DiagnosticUnderlineHint = { sp = p.accent, undercurl = true },
  DiagnosticVirtualTextError = { fg = p.bad, bg = p.raised },
  DiagnosticVirtualTextWarn = { fg = p.warn, bg = p.raised },
  DiagnosticVirtualTextInfo = { fg = p.link, bg = p.raised },
  DiagnosticVirtualTextHint = { fg = p.accent, bg = p.raised },

  -- ---- LSP -----------------------------------------------------------------
  LspReferenceText = { bg = p.raised_hi },
  LspReferenceRead = { bg = p.raised_hi },
  LspReferenceWrite = { bg = p.raised_hi, underline = true },
  LspInlayHint = { fg = p.faint, bg = p.raised },
  LspSignatureActiveParameter = { fg = p.accent, bold = true },

  -- ---- treesitter -----------------------------------------------------------
  ['@variable'] = { fg = p.fg },
  ['@variable.builtin'] = { fg = a[5], italic = true },
