  ['@punctuation.bracket'] = { fg = p.muted },
  ['@punctuation.delimiter'] = { fg = p.muted },
  ['@comment'] = { fg = p.faint, italic = true },
  ['@comment.error'] = { fg = p.bg, bg = p.bad, bold = true },
  ['@comment.warning'] = { fg = p.bg, bg = p.warn, bold = true },
  ['@comment.todo'] = { fg = p.bg, bg = p.accent, bold = true },
  ['@comment.note'] = { fg = p.bg, bg = p.link, bold = true },
  ['@markup.heading'] = { fg = p.accent, bold = true },
  ['@markup.link'] = { fg = p.link, underline = true },
  ['@markup.raw'] = { fg = a[2] },
  ['@markup.list'] = { fg = p.muted },
  ['@diff.plus'] = { fg = p.good },
  ['@diff.minus'] = { fg = p.bad },
  ['@tag'] = { fg = a[5] },
  ['@tag.attribute'] = { fg = a[4] },
  ['@tag.delimiter'] = { fg = p.muted },

  -- ---- telescope --------------------------------------------------------------
  -- The switcher itself runs in telescope, so this is the first thing seen.
  TelescopeNormal = { fg = p.fg, bg = p.raised },
  TelescopeBorder = { fg = p.edge, bg = p.raised },
  TelescopeTitle = { fg = p.accent, bold = true },
  TelescopePromptNormal = { fg = p.fg, bg = p.raised_hi },
  TelescopePromptBorder = { fg = p.raised_hi, bg = p.raised_hi },
  TelescopePromptTitle = { fg = p.bg, bg = p.accent, bold = true },
  TelescopePromptPrefix = { fg = p.accent, bg = p.raised_hi },
  TelescopeSelection = { fg = p.fg, bg = p.selection, bold = true },
  TelescopeSelectionCaret = { fg = p.accent, bg = p.selection },
  TelescopeMatching = { fg = p.warn, bold = true },
  TelescopeResultsComment = { fg = p.faint },

  -- ---- common plugins ------------------------------------------------------
  NvimTreeNormal = { fg = p.muted, bg = p.bg },
  NvimTreeFolderIcon = { fg = p.accent },
  NvimTreeRootFolder = { fg = p.accent, bold = true },
  NvimTreeGitDirty = { fg = p.warn },
