  CmpItemAbbr = { fg = p.muted },
  CmpItemAbbrMatch = { fg = p.accent, bold = true },
  CmpItemKind = { fg = p.link },
  CmpItemMenu = { fg = p.faint },
  NotifyERRORBorder = { fg = p.bad },
  NotifyWARNBorder = { fg = p.warn },
