for group, spec in pairs(groups) do
  vim.api.nvim_set_hl(0, group, spec)
end

-- Terminal colours inside :terminal, so a shell in a split matches kitty.
for i = 0, 15 do
  vim.g['terminal_color_' .. i] = a[i]
end
